-- Files of a candidate (CV, identity documents, certificates, photo). The file itself is in the private
-- bucket under storage_key (generated by the backend); file_name is only the original name (metadata).
CREATE TABLE documents (
    id             UUID PRIMARY KEY,
    candidate_id   UUID                     NOT NULL,
    type           VARCHAR(20)              NOT NULL,
    file_name      VARCHAR(255)             NOT NULL,
    -- Detected from the content, never from the Content-Type sent by the client
    mime_type      VARCHAR(100)             NOT NULL,
    size_bytes     BIGINT                   NOT NULL,
    storage_key    VARCHAR(200)             NOT NULL,
    sha256         VARCHAR(64)              NOT NULL,
    status         VARCHAR(10)              NOT NULL,
    -- Number of the BI / NIF / INSS (sensitive: only in the document details)
    reference      VARCHAR(20),
    expires_at     DATE,
    reviewed_by_id UUID,
    reviewed_at    TIMESTAMP WITH TIME ZONE,
    rejection_note VARCHAR(500),
    uploaded_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     UUID,
    updated_by     UUID,
    CONSTRAINT uk_documents_storage_key UNIQUE (storage_key),
    CONSTRAINT fk_documents_candidate FOREIGN KEY (candidate_id) REFERENCES candidates (id) ON DELETE CASCADE,
    CONSTRAINT fk_documents_reviewed_by FOREIGN KEY (reviewed_by_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_documents_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_documents_updated_by FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_documents_type CHECK (type IN ('CV', 'BI', 'NIF', 'INSS', 'CRIMINAL_RECORD', 'MEDICAL_CERTIFICATE', 'CERTIFICATE', 'PHOTO', 'OTHER')),
    CONSTRAINT ck_documents_status CHECK (status IN ('SUBMITTED', 'APPROVED', 'REJECTED')),
    CONSTRAINT ck_documents_size CHECK (size_bytes > 0)
);

CREATE INDEX ix_documents_candidate_id ON documents (candidate_id, uploaded_at DESC);

-- Current CV and profile photo of the candidate
ALTER TABLE candidates
    ADD COLUMN photo_document_id UUID,
    ADD CONSTRAINT fk_candidates_cv_document FOREIGN KEY (cv_document_id) REFERENCES documents (id) ON DELETE SET NULL,
    ADD CONSTRAINT fk_candidates_photo_document FOREIGN KEY (photo_document_id) REFERENCES documents (id) ON DELETE SET NULL;
